import React, { useEffect, useState } from "react";
import axios from "axios";

import {
  Card,
  CardContent,
  Typography,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  TextField,
  Box,
  AppBar,
  Toolbar,
  Avatar,
  Drawer,
  Divider,
  List,
  ListItem,
  ListItemText,
  Button,
} from "@mui/material";

import {
  Warning,
  CheckCircle,
  Error,
} from "@mui/icons-material";

function Dashboard() {
  const [buyers, setBuyers] = useState([]);
  const [search, setSearch] = useState("");

  useEffect(() => {
    axios
      .get("http://localhost:8000/buyers")
      .then((response) => {
        setBuyers(response.data);
      })
      .catch((error) => {
        console.error(error);
      });
  }, []);

  const filteredBuyers = buyers.filter((buyer) =>
    buyer.name.toLowerCase().includes(search.toLowerCase())
  );

  const greenCount = buyers.filter(
    (b) => b.risk_level === "GREEN"
  ).length;

  const amberCount = buyers.filter(
    (b) => b.risk_level === "AMBER"
  ).length;

  const redCount = buyers.filter(
    (b) => b.risk_level === "RED"
  ).length;

  const getChipColor = (level) => {
    if (level === "RED") return "error";
    if (level === "AMBER") return "warning";
    return "success";
  };

  return (
    <Box sx={{ backgroundColor: "#f4f6f8", minHeight: "100vh" }}>
      <AppBar position="static" sx={{ backgroundColor: "#0f172a" }}>
        <Toolbar>
          <Avatar sx={{ mr: 2 }}>R</Avatar>

          <Typography variant="h6">
            Ecommerce Buyer Risk Dashboard
          </Typography>
        </Toolbar>
      </AppBar>

      <Box sx={{ padding: 4 }}>
        <Grid container spacing={3}>
          <Grid item xs={12} md={4}>
            <Card sx={{ borderRadius: 4 }}>
              <CardContent>
                <Typography variant="h6">
                  Low Risk Buyers
                </Typography>

                <Typography variant="h3" color="green">
                  {greenCount}
                </Typography>

                <CheckCircle color="success" />
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={4}>
            <Card sx={{ borderRadius: 4 }}>
              <CardContent>
                <Typography variant="h6">
                  Medium Risk Buyers
                </Typography>

                <Typography variant="h3" color="orange">
                  {amberCount}
                </Typography>

                <Warning color="warning" />
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={4}>
            <Card sx={{ borderRadius: 4 }}>
              <CardContent>
                <Typography variant="h6">
                  High Risk Buyers
                </Typography>

                <Typography variant="h3" color="red">
                  {redCount}
                </Typography>

                <Error color="error" />
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        <Card sx={{ marginTop: 4, borderRadius: 4 }}>
          <CardContent>
            <Box
              sx={{
                display: "flex",
                justifyContent: "space-between",
                marginBottom: 2,
              }}
            >
              <Typography variant="h6">
                Buyer Investigation Queue
              </Typography>

              <TextField
                size="small"
                placeholder="Search buyer"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </Box>

<TableContainer component={Paper}>
  <Table>
    <TableHead>
      <TableRow>
        <TableCell><b>Buyer ID</b></TableCell>
        <TableCell><b>Name</b></TableCell>
        <TableCell><b>Risk</b></TableCell>
        <TableCell><b>IP Address</b></TableCell>
        <TableCell><b>Fingerprint</b></TableCell>
        <TableCell><b>Shared Accounts</b></TableCell>
        <TableCell><b>Return Ratio</b></TableCell>
        <TableCell><b>Orders 24H</b></TableCell>
        <TableCell><b>Address</b></TableCell>
        <TableCell><b>VPN</b></TableCell>
        <TableCell><b>Promo Abuse</b></TableCell>
        <TableCell><b>Delivery Failures</b></TableCell>
      </TableRow>
    </TableHead>

    <TableBody>
      {filteredBuyers.map((buyer) => (
        <TableRow key={buyer.id} hover>

          <TableCell>{buyer.id}</TableCell>

          <TableCell>{buyer.name}</TableCell>

          <TableCell>
            <Chip
              label={buyer.risk_level}
              color={getChipColor(buyer.risk_level)}
            />
          </TableCell>

          <TableCell>{buyer.ip_address}</TableCell>

          <TableCell>
            {buyer.device_fingerprint}
          </TableCell>

          <TableCell>
            <Chip
              label={buyer.shared_accounts}
              color={
                buyer.shared_accounts > 5
                  ? "error"
                  : buyer.shared_accounts > 2
                  ? "warning"
                  : "success"
              }
            />
          </TableCell>

          <TableCell>
            <Chip
              label={buyer.return_ratio}
              color={
                parseInt(buyer.return_ratio) > 50
                  ? "error"
                  : parseInt(buyer.return_ratio) > 20
                  ? "warning"
                  : "success"
              }
            />
          </TableCell>

          <TableCell>
            <Chip
              label={buyer.orders_last_24h}
              color={
                buyer.orders_last_24h > 10
                  ? "error"
                  : buyer.orders_last_24h > 5
                  ? "warning"
                  : "success"
              }
            />
          </TableCell>

          <TableCell>
            <Chip
              label={buyer.address_quality}
              color={
                buyer.address_quality === "GARBLED"
                  ? "error"
                  : "success"
              }
            />
          </TableCell>

          <TableCell>
            <Chip
              label={
                buyer.vpn_detected ? "Detected" : "Clean"
              }
              color={
                buyer.vpn_detected
                  ? "error"
                  : "success"
              }
            />
          </TableCell>

          <TableCell>
            <Chip
              label={
                buyer.promo_abuse ? "Yes" : "No"
              }
              color={
                buyer.promo_abuse
                  ? "warning"
                  : "success"
              }
            />
          </TableCell>

          <TableCell>
            <Chip
              label={buyer.delivery_failures}
              color={
                buyer.delivery_failures > 3
                  ? "error"
                  : buyer.delivery_failures > 0
                  ? "warning"
                  : "success"
              }
            />
          </TableCell>

        </TableRow>
      ))}
    </TableBody>
  </Table>
</TableContainer>

          </CardContent>
        </Card>
      </Box>
    </Box>
  );
}

export default Dashboard;
